import javax.swing.*;import java.awt.*;import java.sql.*;import java.util.*;
public class ResultWindow extends JFrame {
    public ResultWindow(User u,Map<String,String> choices){setTitle("Vote Summary");setSize(500,320);setLocationRelativeTo(null);JPanel p=UI.panel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("Your vote summary");h.setForeground(Color.WHITE);h.setFont(new Font("SansSerif",Font.BOLD,22));p.add(h);for(String k:choices.keySet()){JLabel l=new JLabel(k+": "+(choices.get(k).equals("None")?"None":candidateName(k,choices.get(k))));l.setForeground(Color.WHITE);p.add(l);}JLabel msg=new JLabel("This window closes in 10 seconds.");msg.setForeground(Color.YELLOW);p.add(msg);add(p);javax.swing.Timer t=new javax.swing.Timer(10000,e->{((javax.swing.Timer)e.getSource()).stop();new Login().setVisible(true);dispose();});t.setRepeats(false);t.start();}
    private String candidateName(String pos,String id){try(Connection c=DbConfig.connect();PreparedStatement s=c.prepareStatement("SELECT candidate_name FROM Candidates WHERE student_id=? AND position=?")){s.setString(1,id);s.setString(2,pos);try(ResultSet r=s.executeQuery()){return r.next()?r.getString(1):"Candidate";}}catch(Exception e){return "Candidate";}}
    public static void showResults(Component parent){try{if("active".equals(UI.electionStatus())){UI.msg(parent,"Results are hidden while election is active.");return;}StringBuilder out=new StringBuilder("FINAL RESULTS\n\n");String[] pos={"General Secretary","Sports Secretary","Vice President","Event Secretary"};try(Connection c=DbConfig.connect()){for(String p:pos){out.append(p).append("\n");try(PreparedStatement s=c.prepareStatement("SELECT candidate_name,votes FROM Candidates WHERE position=? ORDER BY votes DESC,candidate_name")){s.setString(1,p);try(ResultSet r=s.executeQuery()){if(!r.next())out.append("No candidates\n");else{out.append("Winner: ").append(r.getString(1)).append(" ( ").append(r.getInt(2)).append(" votes )\n");do{out.append("  ").append(r.getString(1)).append(" - ").append(r.getInt(2)).append("\n");}while(r.next());}}}out.append("\n");}}JTextArea area=new JTextArea(out.toString());area.setEditable(false);area.setFont(new Font("Monospaced",Font.PLAIN,14));JOptionPane.showMessageDialog(parent,new JScrollPane(area),"Election Results",JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){UI.error(parent,(Exception)e);}}
}
